import java.util.*;

class Solution {
  public List<Integer> countSmaller(int[] nums) {
    final int OFFSET = 10001, SIZE = 20002; // values lie in [-10^4, 10^4]
    int[] bit = new int[SIZE + 1];
    Integer[] ans = new Integer[nums.length];
    for (int i = nums.length - 1; i >= 0; i--) {
      int v = nums[i] + OFFSET, s = 0;
      for (int j = v - 1; j > 0; j -= j & -j) s += bit[j];
      ans[i] = s;
      for (int j = v; j <= SIZE; j += j & -j) bit[j]++;
    }
    return Arrays.asList(ans);
  }
}
